// === Tab: mySketch ===
// port and modification of D'Arch's surfs_Up_Blue -- https://www.openprocessing.org/sketch/298646
// artist: Robert D'Arcy -- https://www.openprocessing.org/user/43968
// note: eliminated pixels and pixel functions - load, modify color, and update - and replace
// with points

// D'Arcy's notes:
// Pixel-sized particles version, of 'surfs_up'.
// Particles are now directly noise driven omitting the flow field.
// Array[], particle, pixel, noise()
// Mouse click to save image, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) adjusts background clear.

let particles = []; //Particle[] particles;
let alpha; //float

function setup() {
  createCanvas(1112, 834);
  background(0);
  noStroke();
  setParticles();
}

function draw() {
	//frameRate(30);
	alpha = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 5, 35);
	fill(0, alpha);
	rect(0, 0, width, height);

	//loadPixels();
	//for (Particle p : particles) {
	//	p.move();
	//}
	//updatePixels();
	for(i=0; i<10000; i++){
		particles[i].move();
	}
}

function setParticles() {
  for (let i = 0; i < 10000; i++) { 
    let x = random(width);
    let y = random(height);
    let adj = map(y, 0, height, 255, 0);
    let c = color(40, adj, 255);
    particles[i]= new Particle(x, y, c);
  }
}

function mousePressed() {
  save('pix.jpg');
}

class Particle {
	constructor(xIn, yIn, cIn){
		this.posX = xIn;
		this.posY = yIn;
		this.c = cIn;
		this.incr = 0.0;
	}

	move() {
	    this.update();
	    this.wrap();
	    this.display();
	}

	update() {
		this.incr += 0.008;
		let theta = noise(this.posX * 0.006, this.posY * 0.004, this.incr) * TWO_PI;
		this.posX += 2 * cos(theta);
		this.posY += 2 * sin(theta);
	}

	display() {
		if (this.posX > 0 && this.posX < width && this.posY > 0  && this.posY < height) {
			//pixels[int(this.posX) + int(this.posY * width)] =  this.c;
			stroke(this.c);
			point(this.posX, this.posY);
		}
	}

	wrap() {
	    if (this.posX < 0) this.posX = width;
	    if (this.posX > width ) this.posX =  0;
	    if (this.posY < 0 ) this.posY = height;
	    if (this.posY > height) this.posY =  0;
  	}
}

